window.POSE_GUIDES = {
  "padangusthasana": "Из стойки наклонитесь от тазобедренных суставов, захватите большие пальцы стоп и вытяните корпус вперёд. На выдохе углубляйте наклон, сохраняя опору на всю стопу и активные ноги.",
  "chaturanga": "Из планки сместите корпус немного вперёд и согните локти назад примерно до прямого угла. Плечо и локоть держите на одной высоте, корпус и таз — одной сильной линией.",
  "adho-mukha": "Из упора направьте таз вверх и назад. Раскройте ладони, удлиняйте спину; колени можно согнуть, если это помогает не округлять поясницу.",
  "virabhadrasana-1": "Поставьте ноги в широкий шаг, разверните таз к передней ноге и согните переднее колено. Вытяните руки вверх, сохраняя опору задней стопы и длину в пояснице.",
  "virabhadrasana-2": "Расставьте ноги широко, переднюю стопу разверните наружу и согните колено над пяткой. Таз и грудную клетку раскройте в сторону, руки вытяните параллельно полу.",
  "virabhadrasana-3": "Перенесите вес на одну ногу и вытяните корпус со второй ногой в противоположные стороны. Держите таз ровным, опорную стопу активной, шею продолжением спины.",
  "utthita-trikonasana": "Из широкой стойки вытяните корпус над передней ногой и опустите нижнюю руку к голени или полу. Раскройте грудную клетку, обе ноги оставьте активными.",
  "parivrtta-trikonasana": "Разверните таз к передней ноге и удлините корпус вперёд. Поставьте противоположную руку рядом с передней ногой и раскройте вторую руку вверх, выполняя скрутку от грудного отдела.",
  "utthita-parsvakonasana": "Согните переднее колено над пяткой, нижнюю ладонь поставьте у стопы. Верхнюю руку вытяните над ухом, создавая одну длинную линию от задней пятки до пальцев.",
  "parivrtta-parsvakonasana": "Из выпада удлините корпус и разверните грудную клетку к согнутой ноге. Противоположную ладонь поставьте у передней стопы, вторую руку направьте вверх.",
  "ardha-chandrasana": "Перенесите вес на переднюю ногу, поставьте нижнюю ладонь под плечом и поднимите вторую ногу. Раскройте таз и грудную клетку, верхнюю руку вытяните вверх; взгляд поднимайте только при устойчивом балансе.",
  "parivrtta-ardha-chandra": "Балансируя на одной ноге и противоположной ладони, вытяните поднятую ногу назад. Разверните грудную клетку к верхней руке, сохраняя таз ровнее, чем в обычном Полумесяце.",
  "prasarita-padottanasana": "Расставьте стопы широко и параллельно, наклонитесь от таза с длинной спиной. В варианте с пальцами удерживайте захват; в варианте с замком уводите сцепленные руки за голову без боли в плечах.",
  "parsvottanasana": "Разверните таз к передней ноге и вытяните корпус над ней. Уходите в наклон от тазобедренных суставов, сохраняя обе ноги активными и пятки устойчивыми.",
  "vrikshasana": "Перенесите вес на одну стопу, вторую поставьте на внутреннюю поверхность бедра или голени, но не на колено. Выровняйте таз, найдите неподвижную точку взгляда и вытянитесь руками вверх.",
  "utthita-hasta": "Устойчиво встаньте на одну ногу, захватите большой палец второй и постепенно выпрямляйте её вперёд. Не округляйте спину ради высоты ноги.",
  "bakasana": "Поставьте ладони на ширине плеч, прижмите колени к плечам и перенесите вес вперёд. Поднимайте стопы только когда опора в ладонях и контроль корпуса устойчивы.",
  "bhujapidasana": "Проведите плечи под бёдра, поставьте ладони за пятками и перенесите вес в руки. Скрестите стопы, выпрямляйте локти без провала в плечах.",
  "tittibhasana": "Поставьте плечи как можно глубже под бёдра и перенесите вес на ладони. Поднимите таз и постепенно выпрямляйте ноги, сохраняя сильный плечевой пояс.",
  "paschimottanasana": "Сядьте с прямыми ногами, вытяните позвоночник вверх и наклонитесь от таза. Захват выбирайте по доступности, не тяните корпус к ногам силой.",
  "triang-mukha": "Одну ногу вытяните, вторую согните как в Вирасане. Выровняйте таз и наклоняйтесь к прямой ноге с длинной передней поверхностью корпуса.",
  "baddha-konasana": "Соедините стопы и приблизьте пятки к тазу настолько, насколько удобно коленям. Вытяните позвоночник, а наклон выполняйте от тазобедренных суставов.",
  "padmasana": "Размещайте стопы на противоположных бёдрах только при свободном движении тазобедренных суставов. Для доступного варианта оставьте одну стопу в полулотосе; колени не прижимайте силой.",
  "ashtavakrasana": "Заведите бедро высоко на плечо, перенесите вес на ладони и скрестите стопы. Выпрямляйте ноги в сторону, удерживая плечи активными и локти под контролем.",
  "navasana": "Поднимите голени или прямые ноги, балансируя на седалищных костях. Вытяните грудную клетку вверх, не позволяя пояснице округляться и проваливаться.",
  "janu-sirsasana": "Согните одну ногу и разверните колено в сторону, вторую оставьте прямой. Поверните корпус к прямой ноге и наклонитесь от таза без рывка.",
  "urdhva-mukha": "Из положения на животе или низкой планки выпрямите руки и раскройте грудную клетку вперёд и вверх. Опирайтесь на ладони и подъёмы стоп, не сжимайте поясницу.",
  "bhujangasana": "Лёжа на животе, поставьте ладони под плечами и поднимайте грудную клетку работой спины. Локти оставьте направленными назад, таз и ноги — на полу.",
  "dhanurasana": "Лёжа на животе, согните колени и захватите лодыжки. Отталкивайте стопы назад и вверх, поднимая грудную клетку без резкого сжатия поясницы.",
  "shalabhasana": "Лёжа на животе, вытяните руки назад и поднимите грудную клетку с ногами. Удлиняйтесь в обе стороны и не запрокидывайте голову.",
  "ushtrasana": "Встаньте на колени, вытяните боковые поверхности корпуса и раскройте грудную клетку. Уводите таз вперёд, ладони поставьте на пятки без провала в пояснице.",
  "urdhva-dhanurasana": "Поставьте стопы у таза, ладони у ушей и поднимитесь через опору рук и ног. Колени направляйте вперёд, грудную клетку — от стоп, не разваливая локти в стороны.",
  "salamba-sarvangasana": "Поднимите таз и ноги, поддержите спину ладонями и вытяните корпус вверх. Вес распределяйте по плечам и рукам, не переносите его на шею.",
  "halasana": "Из стойки на плечах опустите прямые ноги за голову. Сохраняйте опору на плечи и длину шеи; при необходимости оставьте стопы на опоре.",
  "karnapidasana": "Из Халасаны мягко согните колени к сторонам головы. Не давите коленями на уши и сохраняйте свободное дыхание и опору на плечи.",
  "salamba-sirsasana": "Сформируйте устойчивую опору предплечьями и макушкой, поднимайте ноги без толчка. Основную работу несут предплечья и плечевой пояс; осваивайте позу с преподавателем.",
  "hanumanasana": "Из выпада постепенно раздвигайте ноги в противоположные стороны, удерживая таз направленным вперёд. Используйте опоры под таз и не проваливайтесь глубже доступного диапазона.",
  "pincha-mayurasana": "Поставьте предплечья параллельно и активно оттолкнитесь ими от пола. Поднимайте ноги с контролем, удерживая плечи над локтями; стену используйте как страховку.",
  "vasisthasana": "Из планки перенесите вес на одну ладонь и внешний край стопы. Поднимите таз, раскройте грудную клетку и вытяните верхнюю руку или захваченную ногу.",
  "vishvamitrasana": "Из бокового упора проведите верхнюю ногу над плечом и захватите стопу. Выпрямляйте ногу только при устойчивой опоре ладони и свободном плечевом суставе.",
  "kurmasana": "Разведите ноги, проведите руки под коленями и постепенно опустите корпус вперёд. В полном варианте соедините стопы и сцепите пальцы за спиной без давления на колени.",
  "yoga-nidrasana": "Поочерёдно заведите ноги за плечи и голову, сохраняя спокойное дыхание. Руки положите на пол или заведите под таз; выполняйте только после достаточной подготовки.",
  "upavistha-konasana": "Сядьте с широко разведёнными прямыми ногами и направьте колени вверх. Наклоняйтесь от таза с длинной спиной; боковой вариант выполняйте без сворачивания грудной клетки вниз.",
  "padahastasana": "В наклоне заведите ладони под стопы пальцами к пяткам. Переносите вес равномерно и вытягивайте спину, не переразгибая колени.",
  "ardha-baddha-padmottanasana": "Поместите одну стопу в полулотос и захватите её рукой за спиной. Наклонитесь к опорной ноге и поставьте свободную ладонь полностью на пол, не скручивая опорное колено.",
  "eka-pada-sirsasana": "Подготовленную ногу заведите за плечо и затем за голову, сохраняя вытяжение позвоночника. Не тяните стопу силой и прекратите движение при давлении в колене или шее.",
  "adho-mukha-vrikshasana": "Поставьте ладони на ширине плеч, активно оттолкнитесь от пола и поднимите ноги с контролем. Удерживайте плечи раскрытыми и корпус собранным; осваивайте у стены или с преподавателем.",
  "krounchasana": "Сядьте, одну ногу согните как в Вирасане, вторую захватите за стопу и поднимите. Выпрямляйте колено, сохраняя вертикальный корпус и ровный таз.",
  "virasana": "Сядьте между стопами, направив колени вперёд. Если таз не опускается свободно, используйте опору; вытяните позвоночник и поднимите руки.",
  "supta-virasana": "Из Вирасаны опускайтесь назад на предплечья или опору, сохраняя колени направленными вперёд. Не допускайте боли в коленях и пояснице.",
  "marichyasana": "Согните одну ногу и поставьте стопу у таза. Для скрутки разворачивайтесь от грудного отдела; для наклона удлиняйте корпус вперёд, сохраняя замок рук без натяжения плеча.",
  "ardha-matsyendrasana": "Сядьте устойчиво, перенесите одну стопу за противоположное колено и вытянитесь вверх. Скручивайтесь снизу вверх, не используя рычаг руки для насильственного поворота.",
  "parivrtta-janu": "Одну ногу вытяните в сторону, вторую согните. Выполните боковой наклон и разверните грудную клетку вверх, удерживая обе стороны корпуса длинными.",
  "eka-pada-galavasana": "Положите голень на плечи из баланса стоя, перенесите вес в ладони и согните локти. Поднимите таз и вытяните заднюю ногу вверх и назад без провала в плечах.",
  "niralamba-sarvangasana": "Из устойчивой стойки на плечах уберите поддержку рук и вытяните их вдоль пола или корпуса. Сохраняйте вес на плечах, а не на шее; вариант требует уверенной базовой Сарвангасаны.",
  "shavasana": "Лягте симметрично, разведите стопы и разверните ладони вверх. Отпустите усилие в лице, плечах и животе, сохраняя естественное дыхание.",
  "parsva-bakasana": "Из глубокого приседа выполните скрутку и поставьте ладони на пол. Перенесите вес вперёд, удерживая колени вместе и плечевой пояс активным.",
  "agni-stambhasana": "Расположите голени одну перед другой, обе стопы оставьте активными, голеностопы не заламывайте. Если между верхним коленом и нижней ногой остаётся пространство, передвиньте верхнюю стопу вперёд, чтобы пятка оказалась перед коленом нижней ноги; наклон выполняйте от таза.",
};
